#include <cstdio>
#include <cstdint>
#include <atomic>
#include <thread>

// 同一行：a、b 相邻（偏移 8），结构体整体 64 字节对齐 → 必在同一缓存行
struct alignas(64) Packed {
    std::atomic<long long> a{0};
    std::atomic<long long> b{0};
};
// 对齐后：b 被推到偏移 64 → 与 a 分处两条缓存行
struct alignas(64) Padded {
    std::atomic<long long> a{0};
    char pad[64 - sizeof(std::atomic<long long>)];
    std::atomic<long long> b{0};
};
Packed g_packed;
Padded g_padded;

// 确定性模型：两核交替写各自的计数器，统计"缓存行在核间迁移"的次数。
// 同一行 → 每写一次都要把整行搬过来（迁移数 ≈ 迭代数）；
// 分开两行 → 各自首次加载后不再迁移（迁移数 ≈ 2）。
long long transfers(bool same_line, int iters) {
    int ownerA = -1, ownerB = -1;
    long long t = 0;
    for (int i = 0; i < iters; ++i) {
        int core = i & 1;                 // 交替：核 0 写 a、核 1 写 b
        if (same_line) {
            if (ownerA != core) { ++t; ownerA = core; ownerB = core; }
        } else {
            if (core == 0) { if (ownerA != 0) { ++t; ownerA = 0; } }
            else           { if (ownerB != 1) { ++t; ownerB = 1; } }
        }
    }
    return t;
}

int main() {
    auto line = [](const void* p) { return (uintptr_t)p / 64; };
    printf("Packed a/b 同一缓存行: %d\n",
           (int)(line(&g_packed.a) == line(&g_packed.b)));
    printf("Padded a/b 同一缓存行: %d\n",
           (int)(line(&g_padded.a) == line(&g_padded.b)));

    const int N = 2000000;
    printf("模型(同一行) 迁移=%lld\n", transfers(true,  N));
    printf("模型(对齐后) 迁移=%lld\n", transfers(false, N));

    // 真实两线程自增：只输出确定性结果（各自终值），不输出耗时
    const int M = 100000;
    std::thread t1([&]{ for (int i = 0; i < M; ++i) g_packed.a.fetch_add(1, std::memory_order_relaxed); });
    std::thread t2([&]{ for (int i = 0; i < M; ++i) g_packed.b.fetch_add(1, std::memory_order_relaxed); });
    t1.join();
    t2.join();
    printf("真实自增终值 a=%lld b=%lld\n",
           (long long)g_packed.a.load(), (long long)g_packed.b.load());
    return 0;
}
